class DataRooms:
    """Data rooms: Data rooms, their index, guests, folders, documents, Q&A and request lists.

    Access it as ``client.data_rooms``.
    """

    guests: DataRoomsGuests
    access_requests: DataRoomsAccessRequests
    signature_requests: DataRoomsSignatureRequests
    questions: DataRoomsQuestions
    request_items: DataRoomsRequestItems
    folders: DataRoomsFolders
    documents: DataRoomsDocuments

    def __init__(self, client: "HelpRange") -> None:
        self._client = client
        self.guests = DataRoomsGuests(client)
        self.access_requests = DataRoomsAccessRequests(client)
        self.signature_requests = DataRoomsSignatureRequests(client)
        self.questions = DataRoomsQuestions(client)
        self.request_items = DataRoomsRequestItems(client)
        self.folders = DataRoomsFolders(client)
        self.documents = DataRoomsDocuments(client)

    def list(
        self,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> ListDataRoomsResponse:
        """List data rooms.

        Data rooms with guest and document counts (administrators: every room; members: the rooms they created).

        ``GET /api/v2/data-rooms`` – scope ``rooms:read``
        Docs: https://www.helprange.com/developers/api/list-data-rooms
        """
        return cast('ListDataRoomsResponse', self._client._request("GET", "/api/v2/data-rooms", options=request_options))

    def create(
        self,
        *,
        name: str,
        folders: Optional[List[str]] = None,
        settings: Optional[CreateDataRoomBodySettings] = None,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> CreateDataRoomResponse:
        """Create a data room.

        Creates a data room, like "New data room" in the panel, with optional folders (one level – no folders inside folders) and settings. Defaults: watermark on, download off, no screenshot protection, guest notifications on, no NDA, no expiry (a default the plan does not include is left off; a setting you ASK for that the plan does not include: 402 naming the plan). The name must be unique in the team (400). Pro: up to 3 active rooms (402 when the limit is reached); Max, Unlimited, the Deal Room Pass and the trial: unlimited. Next: add documents (Add documents to a data room) and invite guests (Invite a guest) – invitations go out once the room has a document. Answers 201 with the room, including links.guest_link.

        ``POST /api/v2/data-rooms`` – scope ``rooms:write``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/create-data-room
        """
        return cast('CreateDataRoomResponse', self._client._request("POST", "/api/v2/data-rooms", json=_clean({"name": name, "folders": folders, "settings": settings}), idempotency_key=idempotency_key, options=request_options))

    def get(
        self,
        data_room_id: int,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> GetDataRoomResponse:
        """Data room details.

        Settings, links (guest link, panel), guests (views, last visit, NDA status, their own invitation link), documents, freeze status with closing archives, and Q&A counts.

        ``GET /api/v2/data-rooms/{data_room_id}`` – scope ``rooms:read``
        Docs: https://www.helprange.com/developers/api/get-data-room
        """
        return cast('GetDataRoomResponse', self._client._request("GET", f"/api/v2/data-rooms/{_path(data_room_id)}", options=request_options))

    def update(
        self,
        data_room_id: int,
        *,
        name: Optional[str] = None,
        settings: Optional[CreateDataRoomBodySettings] = None,
        folders_enabled: Optional[bool] = None,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> UpdateDataRoomResponse:
        """Change a data room.

        Renames the room (name: what guests see) and / or changes its settings, like the room's Settings window: watermark, download, screenshot protection, notifications, expiry, NDA on / off (nda, nda_id, nda_template, nda_mode), Q&A, access requests, room folders. Only what is sent changes; the room's documents take the new settings (within what each file type allows). Only a setting switched ON is checked against the plan (402) – a room keeps what it has, switching off is always allowed. Turning folders off deletes the room's folders; their documents stay in the room (409 when the room is frozen). Answers with the room.

        ``POST /api/v2/data-rooms/{data_room_id}`` – scope ``rooms:write``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/update-data-room
        """
        return cast('UpdateDataRoomResponse', self._client._request("POST", f"/api/v2/data-rooms/{_path(data_room_id)}", json=_clean({"name": name, "settings": settings, "folders_enabled": folders_enabled}), idempotency_key=idempotency_key, options=request_options))

    def delete(
        self,
        data_room_id: int,
        *,
        confirm: bool,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> DeleteDataRoomResponse:
        """Delete a data room.

        Like "Delete data room" in the panel: guests lose access at once and the room's links stop working; the documents stay in their folders. Cannot be undone, so the body must carry "confirm": true – without it the answer is 400 {"error": "confirmation_required", "message"} and nothing is deleted.

        ``POST /api/v2/data-rooms/{data_room_id}/delete`` – scope ``rooms:write``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/delete-data-room
        """
        return cast('DeleteDataRoomResponse', self._client._request("POST", f"/api/v2/data-rooms/{_path(data_room_id)}/delete", json=_clean({"confirm": confirm}), idempotency_key=idempotency_key, options=request_options))

    def get_index(
        self,
        data_room_id: int,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> GetDataRoomIndexResponse:
        """Data room index.

        The room's numbered index (1, 1.1 …) in the structure guests see – always one level of folders. With room folders on, folder nodes are the room's folders (room_folder_id); otherwise, with "Show Folders" on, the folder the documents come from (folder_id, plus subfolder_id for "Folder / Subfolder"). The numbers exist even while numbering is off for guests (index_numbering false).

        ``GET /api/v2/data-rooms/{data_room_id}/index`` – scope ``rooms:read``
        Docs: https://www.helprange.com/developers/api/get-data-room-index
        """
        return cast('GetDataRoomIndexResponse', self._client._request("GET", f"/api/v2/data-rooms/{_path(data_room_id)}/index", options=request_options))


