class WebhookEndpoints:
    """Webhook endpoints: Manage the team's webhook endpoint: create, change, rotate the signing secret, delivery log, redeliver, test (scope webhooks:manage, administrators, live keys).

    Access it as ``client.webhook_endpoints``.
    """


    def __init__(self, client: "HelpRange") -> None:
        self._client = client

    def list(
        self,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> ListWebhookEndpointsResponse:
        """List webhook endpoints.

        The team's webhook endpoint – a team has at most one, so the list has 0 or 1 items. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``GET /api/v2/webhook-endpoints`` – scope ``webhooks:manage``
        Docs: https://www.helprange.com/developers/api/list-webhook-endpoints
        """
        return cast('ListWebhookEndpointsResponse', self._client._request("GET", "/api/v2/webhook-endpoints", options=request_options))

    def create(
        self,
        *,
        url: str,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> CreateWebhookEndpointResponse:
        """Create a webhook endpoint.

        Sets the team's webhook URL (as Settings → Integrations → Webhook) and answers with the signing secret – shown once. Every event is sent to it. 409 endpoint_exists when the team already has one (change its url instead). Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``POST /api/v2/webhook-endpoints`` – scope ``webhooks:manage``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/create-webhook-endpoint
        """
        return cast('CreateWebhookEndpointResponse', self._client._request("POST", "/api/v2/webhook-endpoints", json=_clean({"url": url}), idempotency_key=idempotency_key, options=request_options))

    def get(
        self,
        endpoint_id: int,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> GetWebhookEndpointResponse:
        """Get a webhook endpoint.

        The endpoint: URL, on / off (and why), failures in a row, last success. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``GET /api/v2/webhook-endpoints/{endpoint_id}`` – scope ``webhooks:manage``
        Docs: https://www.helprange.com/developers/api/get-webhook-endpoint
        """
        return cast('GetWebhookEndpointResponse', self._client._request("GET", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}", options=request_options))

    def update(
        self,
        endpoint_id: int,
        *,
        url: Optional[str] = None,
        enabled: Optional[bool] = None,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> UpdateWebhookEndpointResponse:
        """Change a webhook endpoint.

        A new url (a fresh start: on, failure count reset; the signing secret stays), and / or "enabled": true to turn an endpoint that HelpRange switched off (410 Gone or repeated failures) back on – then redeliver what you need. Endpoints are not switched off through the API: delete it to stop webhooks. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``POST /api/v2/webhook-endpoints/{endpoint_id}`` – scope ``webhooks:manage``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/update-webhook-endpoint
        """
        return cast('UpdateWebhookEndpointResponse', self._client._request("POST", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}", json=_clean({"url": url, "enabled": enabled}), idempotency_key=idempotency_key, options=request_options))

    def delete(
        self,
        endpoint_id: int,
        *,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> DeleteWebhookEndpointResponse:
        """Delete a webhook endpoint.

        Stops webhooks at once: the team's webhook URL is cleared and the endpoint, its signing secret and its delivery log are deleted. A new endpoint gets a new secret. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``POST /api/v2/webhook-endpoints/{endpoint_id}/delete`` – scope ``webhooks:manage``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/delete-webhook-endpoint
        """
        return cast('DeleteWebhookEndpointResponse', self._client._request("POST", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}/delete", idempotency_key=idempotency_key, options=request_options))

    def rotate_secret(
        self,
        endpoint_id: int,
        *,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> RotateWebhookSecretResponse:
        """Rotate the signing secret.

        A new signing secret, returned once. For 24 hours the previous secret keeps signing too (a second v1= in HelpRange-Signature), so you can switch without dropping events. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``POST /api/v2/webhook-endpoints/{endpoint_id}/rotate-secret`` – scope ``webhooks:manage``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/rotate-webhook-secret
        """
        return cast('RotateWebhookSecretResponse', self._client._request("POST", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}/rotate-secret", idempotency_key=idempotency_key, options=request_options))

    def send_test(
        self,
        endpoint_id: int,
        *,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> SendWebhookTestEventResponse:
        """Send a test event.

        Sends a document.opened example with "test": true now (one attempt) and answers with the delivery – delivered true when your endpoint answered 2xx. 409 endpoint_disabled while the endpoint is off. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``POST /api/v2/webhook-endpoints/{endpoint_id}/test`` – scope ``webhooks:manage``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/send-webhook-test-event
        """
        return cast('SendWebhookTestEventResponse', self._client._request("POST", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}/test", idempotency_key=idempotency_key, options=request_options))

    def deliveries(
        self,
        endpoint_id: int,
        *,
        status: Optional[Literal['pending', 'delivered', 'failed']] = None,
        limit: Optional[int] = None,
        page: Optional[int] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> ListWebhookDeliveriesResponse:
        """List webhook deliveries.

        The delivery log: every event sent to the endpoint in the last 30 days (older rows are deleted), newest first, with status, attempts, the last answer and the payload. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``GET /api/v2/webhook-endpoints/{endpoint_id}/deliveries`` – scope ``webhooks:manage``
        Docs: https://www.helprange.com/developers/api/list-webhook-deliveries
        """
        return cast('ListWebhookDeliveriesResponse', self._client._request("GET", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}/deliveries", params=_clean({"status": status, "limit": limit, "page": page}), options=request_options))

    def redeliver(
        self,
        endpoint_id: int,
        delivery_id: int,
        *,
        idempotency_key: Optional[str] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> RedeliverWebhookDeliveryResponse:
        """Redeliver a webhook.

        The delivery log's "Resend": one immediate attempt with the same event id (deduplicate on it), no automatic retries after it. 409 endpoint_disabled while the endpoint is off. Scope webhooks:manage; team administrators only (403 otherwise); live keys only – test keys get 400 livemode_required (the sandbox sends no webhooks).

        ``POST /api/v2/webhook-endpoints/{endpoint_id}/deliveries/{delivery_id}/redeliver`` – scope ``webhooks:manage``
        Sent with an Idempotency-Key, so retries are safe (set your own with ``idempotency_key=``).
        Docs: https://www.helprange.com/developers/api/redeliver-webhook-delivery
        """
        return cast('RedeliverWebhookDeliveryResponse', self._client._request("POST", f"/api/v2/webhook-endpoints/{_path(endpoint_id)}/deliveries/{_path(delivery_id)}/redeliver", idempotency_key=idempotency_key, options=request_options))



